CREATE TRIGGER UNDGCommonData_Version_Create
	ON UNDGCommonData
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT DC_PK, 'DC'
	FROM inserted
GO
CREATE TRIGGER UNDGCommonData_Version_Update
	ON UNDGCommonData
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON DC_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER UNDGCommonData_DataChangeHistory
	ON UNDGCommonData
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT DC_PK, 'DC' FROM inserted
	UNION
	SELECT DC_PK, 'DC' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER UNDGCommonData_DataProcessingResult_Delete
	ON UNDGCommonData
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.DC_PK
	END
GO
